-- RoboSynct Phase 4 v1. Additive: existing owner RLS, QR grants and tables remain.
-- Install in the EXISTING Supabase SQL Editor after reviewing the accompanying guide.
begin;
do $$ begin
 if to_regclass('public.projects') is null or to_regclass('public.channels') is null or to_regclass('public.telemetry') is null or to_regclass('public.events') is null then raise exception 'Existing RoboSynct foundation required.';end if;
 if to_regclass('public.rs_phase4_schema') is null and (to_regclass('public.rs_classrooms') is not null or to_regclass('public.rs_cloud_rules') is not null or exists(select 1 from pg_namespace where nspname='rs_phase4_private') or exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('rs_phase4_status','rs_class_list','rs_class_create','rs_class_invite','rs_class_join','rs_class_members','rs_class_set_member','rs_class_share','rs_class_projects','rs_class_project','rs_class_audit','rs_cloud_rule_save','rs_cloud_rule_list')) or exists(select 1 from pg_trigger where tgname='rs_phase4_telemetry_event')) then raise exception 'Phase 4 names already exist; stopped without changing them.';end if;
end $$;
create schema if not exists rs_phase4_private;
revoke all on schema rs_phase4_private from public,anon,authenticated;
create table if not exists public.rs_phase4_schema(version integer primary key check(version=1),enabled boolean not null default true);
insert into public.rs_phase4_schema values(1,true) on conflict do nothing;
alter table public.rs_phase4_schema enable row level security;
revoke all on public.rs_phase4_schema from public,anon,authenticated;
create table if not exists public.rs_classrooms(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),name text not null check(length(name) between 1 and 80),created_at timestamptz not null default now());
create table if not exists public.rs_class_members(class_id uuid references public.rs_classrooms(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text not null check(role in('teacher','student','operator','viewer')),status text not null check(status in('pending','active','revoked')),created_at timestamptz not null default now(),primary key(class_id,user_id));
create table if not exists public.rs_class_shares(class_id uuid references public.rs_classrooms(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,owner_id uuid not null references auth.users(id),visibility text not null check(visibility in('teachers','class')),created_at timestamptz not null default now(),primary key(class_id,project_id));
create table if not exists rs_phase4_private.invites(class_id uuid primary key references public.rs_classrooms(id) on delete cascade,code_hash text not null unique,expires_at timestamptz not null);
create table if not exists rs_phase4_private.join_limits(user_id uuid references auth.users(id) on delete cascade,bucket timestamptz not null,attempts integer not null,primary key(user_id,bucket));
create table if not exists rs_phase4_private.audit(id uuid primary key default gen_random_uuid(),class_id uuid references public.rs_classrooms(id) on delete cascade,actor uuid not null references auth.users(id),action text not null,at timestamptz not null default now());
create table if not exists public.rs_cloud_rules(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,owner_id uuid not null references auth.users(id),channel_id uuid not null references public.channels(id) on delete cascade,name text not null check(length(name) between 1 and 80),operator text not null check(operator in('above','below')),threshold double precision not null,reset_threshold double precision not null,hold_seconds integer not null default 0 check(hold_seconds between 0 and 3600),cooldown_seconds integer not null default 30 check(cooldown_seconds between 0 and 86400),max_gap_seconds integer not null default 30 check(max_gap_seconds between 1 and 3600),severity text not null default 'warning' check(severity in('info','warning','critical')),enabled boolean not null default true,revision integer not null default 1,save_token uuid,save_hash text,created_at timestamptz not null default now());
create table if not exists rs_phase4_private.rule_state(rule_id uuid primary key references public.rs_cloud_rules(id) on delete cascade,revision integer not null,active boolean not null default false,since_at timestamptz,last_trigger timestamptz,last_sample timestamptz);
create table if not exists rs_phase4_private.runner_errors(id uuid primary key default gen_random_uuid(),owner_id uuid,rule_id uuid,error_code text not null,at timestamptz not null default now());
create index if not exists rs_class_member_user on public.rs_class_members(user_id,status);
create index if not exists rs_class_share_project on public.rs_class_shares(project_id);
create index if not exists rs_cloud_rule_channel on public.rs_cloud_rules(channel_id) where enabled;
create index if not exists rs_class_audit_recent on rs_phase4_private.audit(class_id,at desc);
create or replace function rs_phase4_private.require_enabled() returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid=auth.uid();begin if u is null or not exists(select 1 from public.rs_phase4_schema where version=1 and enabled) then raise exception 'Phase 4 is unavailable or sign-in required.' using errcode='42501';end if;return u;end $$;
create or replace function rs_phase4_private.class_role(c uuid) returns text language sql stable security definer set search_path='' as $$
 select case when r.owner_id=auth.uid() then 'owner' else (select m.role from public.rs_class_members m where m.class_id=r.id and m.user_id=auth.uid() and m.status='active') end from public.rs_classrooms r where r.id=c and auth.uid() is not null
$$;
create or replace function rs_phase4_private.require_class(c uuid,manager boolean default false) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid;v_role text;begin u=rs_phase4_private.require_enabled();v_role=rs_phase4_private.class_role(c);if v_role is null or manager and v_role<>'owner' then raise exception 'Classroom access denied.' using errcode='42501';end if;return u;end $$;
create or replace function rs_phase4_private.project_owner(p uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid;begin u=rs_phase4_private.require_enabled();if not exists(select 1 from public.projects where id=p and owner_id=u) then raise exception 'Project owner access required.' using errcode='42501';end if;return u;end $$;
alter table public.rs_classrooms enable row level security;
alter table public.rs_class_members enable row level security;
alter table public.rs_class_shares enable row level security;
alter table public.rs_cloud_rules enable row level security;
drop policy if exists rs_classroom_read on public.rs_classrooms;
create policy rs_classroom_read on public.rs_classrooms for select to authenticated using(rs_phase4_private.class_role(id) is not null);
drop policy if exists rs_member_read on public.rs_class_members;
create policy rs_member_read on public.rs_class_members for select to authenticated using(user_id=auth.uid() or rs_phase4_private.class_role(class_id) in('owner','teacher'));
drop policy if exists rs_share_read on public.rs_class_shares;
create policy rs_share_read on public.rs_class_shares for select to authenticated using(owner_id=auth.uid() or rs_phase4_private.class_role(class_id) in('owner','teacher') or visibility='class' and rs_phase4_private.class_role(class_id) is not null);
drop policy if exists rs_cloud_rule_read on public.rs_cloud_rules;
create policy rs_cloud_rule_read on public.rs_cloud_rules for select to authenticated using(owner_id=auth.uid());
revoke all on public.rs_classrooms,public.rs_class_members,public.rs_class_shares,public.rs_cloud_rules from public,anon,authenticated;
grant select on public.rs_classrooms,public.rs_class_members,public.rs_class_shares,public.rs_cloud_rules to authenticated;
create or replace function public.rs_phase4_status() returns jsonb language plpgsql security definer set search_path='' as $$
begin perform rs_phase4_private.require_enabled();return jsonb_build_object('installed',true,'version',1,'classrooms',true,'cloud_rules',true,'camera_transport','private_pinned_tls_relay','motor_operations','deferred');end $$;
create or replace function public.rs_class_list() returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;result jsonb;begin u=rs_phase4_private.require_enabled();select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'role',rs_phase4_private.class_role(r.id)) order by r.created_at),'[]'::jsonb) into result from public.rs_classrooms r where rs_phase4_private.class_role(r.id) is not null;return result;end $$;
create or replace function public.rs_class_create(p_name text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;r public.rs_classrooms;begin u=rs_phase4_private.require_enabled();if p_name is null or length(btrim(p_name)) not between 1 and 80 then raise exception 'Class name must be 1–80 characters.';end if;if(select count(*) from public.rs_classrooms where owner_id=u)>=10 then raise exception 'Ten-classroom limit reached.';end if;insert into public.rs_classrooms(owner_id,name) values(u,btrim(p_name)) returning * into r;insert into public.rs_class_members values(r.id,u,'teacher','active',now());insert into rs_phase4_private.audit(class_id,actor,action) values(r.id,u,'class_created');return jsonb_build_object('id',r.id,'name',r.name,'role','owner');end $$;
create or replace function public.rs_class_invite(p_class uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;code text;begin u=rs_phase4_private.require_class(p_class,true);code=substr(replace(gen_random_uuid()::text,'-',''),1,16);insert into rs_phase4_private.invites values(p_class,encode(sha256(convert_to(code,'UTF8')),'hex'),now()+interval '7 days') on conflict(class_id) do update set code_hash=excluded.code_hash,expires_at=excluded.expires_at;insert into rs_phase4_private.audit(class_id,actor,action) values(p_class,u,'invite_rotated');return jsonb_build_object('code',code,'expires_at',now()+interval '7 days','approval_required',true);end $$;
create or replace function public.rs_class_join(p_code text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;c uuid;n integer;begin u=rs_phase4_private.require_enabled();insert into rs_phase4_private.join_limits values(u,date_trunc('hour',now()),1) on conflict(user_id,bucket) do update set attempts=rs_phase4_private.join_limits.attempts+1 returning attempts into n;if n>20 then return jsonb_build_object('status','limited');end if;if p_code is null or p_code!~'^[a-f0-9]{16}$' then return jsonb_build_object('status','invalid');end if;select class_id into c from rs_phase4_private.invites where code_hash=encode(sha256(convert_to(p_code,'UTF8')),'hex') and expires_at>now();if c is null then return jsonb_build_object('status','invalid');end if;if(select count(*) from public.rs_class_members where class_id=c)>=100 then return jsonb_build_object('status','full');end if;insert into public.rs_class_members values(c,u,'student','pending',now()) on conflict(class_id,user_id) do update set status='pending',role='student' where public.rs_class_members.status<>'active';insert into rs_phase4_private.audit(class_id,actor,action) values(c,u,'join_requested');return jsonb_build_object('status',case when rs_phase4_private.class_role(c) is null then 'pending' else 'active' end);end $$;
create or replace function public.rs_class_members(p_class uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;v_role text;result jsonb;begin u=rs_phase4_private.require_class(p_class);v_role=rs_phase4_private.class_role(p_class);select coalesce(jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',m.role,'status',m.status) order by m.created_at),'[]'::jsonb) into result from public.rs_class_members m where m.class_id=p_class and (v_role in('owner','teacher') or m.user_id=u);return result;end $$;
create or replace function public.rs_class_set_member(p_class uuid,p_user uuid,p_role text,p_active boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;begin u=rs_phase4_private.require_class(p_class,true);if p_user=u or p_role not in('teacher','student','operator','viewer') then raise exception 'Owner role cannot change; choose a supported member role.';end if;update public.rs_class_members set role=p_role,status=case when p_active then 'active' else 'revoked' end where class_id=p_class and user_id=p_user;if not found then raise exception 'Member request not found.';end if;if not p_active then delete from public.rs_class_shares where class_id=p_class and owner_id=p_user;end if;insert into rs_phase4_private.audit(class_id,actor,action) values(p_class,u,case when p_active then 'member_approved' else 'member_revoked' end);return jsonb_build_object('saved',true);end $$;
create or replace function public.rs_class_share(p_class uuid,p_project uuid,p_visibility text,p_enabled boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;begin u=rs_phase4_private.require_class(p_class);perform rs_phase4_private.project_owner(p_project);if p_visibility not in('teachers','class') then raise exception 'Choose teachers or whole-class visibility.';end if;if p_enabled then insert into public.rs_class_shares values(p_class,p_project,u,p_visibility,now()) on conflict(class_id,project_id) do update set visibility=excluded.visibility,owner_id=excluded.owner_id;else delete from public.rs_class_shares where class_id=p_class and project_id=p_project and owner_id=u;end if;insert into rs_phase4_private.audit(class_id,actor,action) values(p_class,u,case when p_enabled then 'project_shared_read_only' else 'project_unshared' end);return jsonb_build_object('saved',true);end $$;
create or replace function public.rs_class_projects(p_class uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;v_role text;result jsonb;begin u=rs_phase4_private.require_class(p_class);v_role=rs_phase4_private.class_role(p_class);select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'visibility',s.visibility,'mine',p.owner_id=u,'permissions',jsonb_build_object('view',true,'edit',p.owner_id=u,'drive',false)) order by p.name),'[]'::jsonb) into result from public.rs_class_shares s join public.projects p on p.id=s.project_id and p.owner_id=s.owner_id where s.class_id=p_class and (s.owner_id=u or v_role in('owner','teacher') or s.visibility='class');return result;end $$;
create or replace function public.rs_class_project(p_class uuid,p_project uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;v_role text;p public.projects;d public.widgets;sources jsonb;event_rows jsonb;begin u=rs_phase4_private.require_class(p_class);v_role=rs_phase4_private.class_role(p_class);if not exists(select 1 from public.rs_class_shares s join public.projects x on x.id=s.project_id and x.owner_id=s.owner_id where s.class_id=p_class and s.project_id=p_project and (s.owner_id=u or v_role in('owner','teacher') or s.visibility='class')) then raise exception 'Shared project access denied.' using errcode='42501';end if;select * into p from public.projects where id=p_project;select * into d from public.widgets where id=p_project and project_id=p_project and widget_type='note';select coalesce(jsonb_agg(jsonb_build_object('device',jsonb_build_object('id',dev.id,'label',dev.label,'board_model',dev.board_model,'config',jsonb_build_object('mode',dev.config->>'mode')),'channel',jsonb_build_object('id',ch.id,'device_id',ch.device_id,'channel_key',ch.channel_key,'title',ch.title,'unit',ch.unit,'value_type',ch.value_type,'direction',ch.direction),'readings',coalesce((select jsonb_agg(to_jsonb(t) order by t.recorded_at,t.id) from(select id,channel_id,value_num,value_text,value_bool,recorded_at,received_at,quality from public.telemetry where channel_id=ch.id order by recorded_at desc,id desc limit 100)t),'[]'::jsonb))),'[]'::jsonb) into sources from (select c.* from public.channels c join public.devices v on v.id=c.device_id where v.project_id=p_project and c.id::text in(select value->>'channel_id' from jsonb_array_elements(case when jsonb_typeof(d.config->'widgets')='array' then d.config->'widgets' else '[]'::jsonb end)) order by c.id limit 24)ch join public.devices dev on dev.id=ch.device_id;select coalesce(jsonb_agg(to_jsonb(e) order by e.occurred_at desc),'[]'::jsonb) into event_rows from(select ev.id,ev.device_id,ev.event_type,ev.severity,ev.title,ev.occurred_at,ev.acknowledged_at,jsonb_build_object('source',ev.detail->'source') as detail from public.events ev join public.devices v on v.id=ev.device_id where v.project_id=p_project order by ev.occurred_at desc,ev.id desc limit 50)e;return jsonb_build_object('project',jsonb_build_object('id',p.id,'name',p.name,'description',p.description),'dashboard',case when d.id is null then null else jsonb_build_object('id',d.id,'revision',d.revision,'config',d.config-'camera_token'-'wifi_password') end,'sources',sources,'events',event_rows,'can_arrange',false,'permissions',jsonb_build_object('view',true,'edit',false,'drive',false),'refreshed_at',now());end $$;
create or replace function public.rs_class_audit(p_class uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;v_role text;result jsonb;begin u=rs_phase4_private.require_class(p_class);v_role=rs_phase4_private.class_role(p_class);select coalesce(jsonb_agg(to_jsonb(a) order by a.at desc),'[]'::jsonb) into result from(select id,actor,action,at from rs_phase4_private.audit where class_id=p_class and (v_role in('owner','teacher') or actor=u) order by at desc limit 50)a;return result;end $$;
-- Cloud automations append EVENTS only; they cannot drive, configure or switch outputs.
create or replace function public.rs_cloud_rule_save(p_project uuid,p_rule jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;v_id uuid;ch uuid;v_token uuid;v_hash text;r public.rs_cloud_rules;old public.rs_cloud_rules;expected integer;
begin
 u=rs_phase4_private.project_owner(p_project);
 if p_rule is null or jsonb_typeof(p_rule)<>'object' or pg_column_size(p_rule)>4096 then raise exception 'Invalid cloud rule.';end if;
 v_id=(p_rule->>'id')::uuid;ch=(p_rule->>'channel_id')::uuid;v_token=(p_rule->>'save_token')::uuid;expected=coalesce((p_rule->>'revision')::integer,0);v_hash=encode(sha256(convert_to((p_rule-'revision'-'last_error'-'save_hash')::text,'UTF8')),'hex');
 if v_id is null or v_token is null or not exists(select 1 from public.channels c join public.devices d on d.id=c.device_id where c.id=ch and d.project_id=p_project and d.config->>'mode'='hardware' and c.value_type='number' and c.direction='input') then raise exception 'Choose an owned hardware numeric input and stable save token.' using errcode='42501';end if;
 select * into old from public.rs_cloud_rules where id=v_id;
 if found then
  if old.owner_id<>u or old.project_id<>p_project then raise exception 'Rule access denied.' using errcode='42501';end if;
  if old.save_token=v_token and old.save_hash=v_hash then return to_jsonb(old)-'owner_id'-'save_hash';end if;
  if old.revision<>expected then raise exception 'Cloud rule changed. Refresh before saving.' using errcode='40001';end if;
 end if;
 if abs((p_rule->>'threshold')::double precision)>1e9 or abs((p_rule->>'reset_threshold')::double precision)>1e9 or (p_rule->>'threshold') in('NaN','Infinity','-Infinity') or (p_rule->>'reset_threshold') in('NaN','Infinity','-Infinity') or p_rule->>'operator'='above' and (p_rule->>'reset_threshold')::double precision>(p_rule->>'threshold')::double precision or p_rule->>'operator'='below' and (p_rule->>'reset_threshold')::double precision<(p_rule->>'threshold')::double precision then raise exception 'Invalid threshold or reset range.';end if;
 if(select count(*) from public.rs_cloud_rules where project_id=p_project)>=24 and old.id is null then raise exception '24-rule project limit reached.';end if;
 insert into public.rs_cloud_rules(id,project_id,owner_id,channel_id,name,operator,threshold,reset_threshold,hold_seconds,cooldown_seconds,max_gap_seconds,severity,enabled,save_token,save_hash)
 values(v_id,p_project,u,ch,p_rule->>'name',p_rule->>'operator',(p_rule->>'threshold')::double precision,(p_rule->>'reset_threshold')::double precision,coalesce((p_rule->>'hold_seconds')::integer,0),coalesce((p_rule->>'cooldown_seconds')::integer,30),coalesce((p_rule->>'max_gap_seconds')::integer,30),coalesce(p_rule->>'severity','warning'),coalesce((p_rule->>'enabled')::boolean,true),v_token,v_hash)
 on conflict on constraint rs_cloud_rules_pkey do update set channel_id=excluded.channel_id,name=excluded.name,operator=excluded.operator,threshold=excluded.threshold,reset_threshold=excluded.reset_threshold,hold_seconds=excluded.hold_seconds,cooldown_seconds=excluded.cooldown_seconds,max_gap_seconds=excluded.max_gap_seconds,severity=excluded.severity,enabled=excluded.enabled,save_token=excluded.save_token,save_hash=excluded.save_hash,revision=case when public.rs_cloud_rules.save_token=v_token and public.rs_cloud_rules.save_hash=v_hash then public.rs_cloud_rules.revision else public.rs_cloud_rules.revision+1 end
 where public.rs_cloud_rules.owner_id=u and public.rs_cloud_rules.project_id=p_project and (public.rs_cloud_rules.revision=expected or public.rs_cloud_rules.save_token=v_token and public.rs_cloud_rules.save_hash=v_hash) returning * into r;
 if not found then raise exception 'Cloud rule changed. Refresh before saving.' using errcode='40001';end if;
 delete from rs_phase4_private.runner_errors where rule_id=r.id;
 return to_jsonb(r)-'owner_id'-'save_hash';
end $$;
create or replace function public.rs_cloud_rule_list(p_project uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;result jsonb;begin u=rs_phase4_private.project_owner(p_project);select coalesce(jsonb_agg((to_jsonb(r)-'owner_id'-'save_hash')||jsonb_build_object('last_error',(select e.error_code from rs_phase4_private.runner_errors e where e.rule_id=r.id order by e.at desc limit 1)) order by r.name),'[]'::jsonb) into result from public.rs_cloud_rules r where project_id=p_project and owner_id=u;return result;end $$;
create or replace function rs_phase4_private.telemetry_event() returns trigger language plpgsql security definer set search_path='' as $$
declare r public.rs_cloud_rules;s rs_phase4_private.rule_state;t timestamptz;qualifies boolean;resets boolean;kind text;device uuid;v_rule uuid;v_owner uuid;begin if not exists(select 1 from public.rs_phase4_schema where version=1 and enabled) then return new;end if;t=new.recorded_at;if t is null or t<now()-interval '2 minutes' or t>now()+interval '2 minutes' then return new;end if;for r in select rule.* from public.rs_cloud_rules rule join public.projects p on p.id=rule.project_id and p.owner_id=rule.owner_id join public.channels c on c.id=rule.channel_id and c.value_type='number' and c.direction='input' join public.devices d on d.id=c.device_id and d.project_id=rule.project_id and d.config->>'mode'='hardware' where rule.enabled and rule.channel_id=new.channel_id loop
 v_rule=r.id;v_owner=r.owner_id;insert into rs_phase4_private.rule_state(rule_id,revision) values(r.id,r.revision) on conflict do nothing;select * into s from rs_phase4_private.rule_state where rule_id=r.id for update;if s.revision<>r.revision then s.revision=r.revision;s.active=false;s.since_at=null;s.last_trigger=null;s.last_sample=null;end if;if s.last_sample is not null and t<=s.last_sample then continue;end if;if s.last_sample is not null and t-s.last_sample>make_interval(secs=>r.max_gap_seconds) then s.active=false;s.since_at=null;end if;s.last_sample=t;kind=null;
 if new.quality not in('ok','estimated') or new.quality is null or new.value_num is null or new.value_num::text in('NaN','Infinity','-Infinity') then s.active=false;s.since_at=null;else qualifies=case when r.operator='above' then new.value_num>r.threshold else new.value_num<r.threshold end;resets=case when r.operator='above' then new.value_num<=r.reset_threshold else new.value_num>=r.reset_threshold end;if s.active then if resets then kind='reset';s.active=false;s.since_at=null;end if;elsif qualifies then if s.since_at is null then s.since_at=t;end if;if t-s.since_at>=make_interval(secs=>r.hold_seconds) and (s.last_trigger is null or t-s.last_trigger>=make_interval(secs=>r.cooldown_seconds)) then kind='triggered';s.active=true;s.last_trigger=t;end if;else s.since_at=null;end if;end if;
 delete from rs_phase4_private.runner_errors where rule_id=r.id;update rs_phase4_private.rule_state set revision=s.revision,active=s.active,since_at=s.since_at,last_trigger=s.last_trigger,last_sample=s.last_sample where rule_id=r.id;
 if kind is not null then select device_id into device from public.channels where id=new.channel_id;insert into public.events(id,device_id,event_type,severity,title,occurred_at,detail) values(gen_random_uuid(),device,'cloud_rule_'||kind,case when kind='triggered' then r.severity else 'info' end,left(case when kind='triggered' then 'Cloud rule: ' else 'Cloud reset: ' end||r.name,200),t,jsonb_build_object('source','cloud_rule','execution','database_on_ingest','rule_id',r.id,'rule_revision',r.revision,'channel_id',new.channel_id,'reading_id',new.id,'value',new.value_num,'quality',new.quality));end if;end loop;return new;exception when others then insert into rs_phase4_private.runner_errors(owner_id,rule_id,error_code) select v_owner,v_rule,sqlstate where not exists(select 1 from rs_phase4_private.runner_errors where rule_id=v_rule and at>now()-interval '1 minute');delete from rs_phase4_private.runner_errors where at<now()-interval '7 days';return new;end $$;
drop trigger if exists rs_phase4_telemetry_event on public.telemetry;
create trigger rs_phase4_telemetry_event after insert on public.telemetry for each row execute function rs_phase4_private.telemetry_event();
-- Deny private tables and unlisted helpers, then expose the exact authenticated surface.
revoke all on all tables in schema rs_phase4_private from public,anon,authenticated;
revoke all on all functions in schema rs_phase4_private from public,anon,authenticated;
grant usage on schema rs_phase4_private to authenticated;
grant execute on function rs_phase4_private.class_role(uuid) to authenticated;
do $$ declare f record;begin for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('rs_phase4_status','rs_class_list','rs_class_create','rs_class_invite','rs_class_join','rs_class_members','rs_class_set_member','rs_class_share','rs_class_projects','rs_class_project','rs_class_audit','rs_cloud_rule_save','rs_cloud_rule_list') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to authenticated',f.signature);end loop;end $$;
notify pgrst,'reload schema';
commit;
select 'Phase 4 v1 installed. Old owner RLS and QR grants are unchanged. Test with two accounts before classroom use.' as result;
